import{_ as n,C as t,o as s,c as o,j as a,a as l,E as i,a2 as d}from"./chunks/framework.DtFQgA2F.js";const f=JSON.parse('{"title":"渲染器原理","description":"","frontmatter":{"title":"渲染器原理"},"headers":[],"relativePath":"notes/03-renderer/renderer.md","filePath":"notes/03-renderer/renderer.md","lastUpdated":1794973014000}'),p={name:"notes/03-renderer/renderer.md"};function c(h,e,_,b,x,m){const r=t("Diagram");return s(),o("div",null,[e[0]||(e[0]=a("h1",{id:"渲染器原理",tabindex:"-1"},[l("渲染器原理 "),a("a",{class:"header-anchor",href:"#渲染器原理","aria-label":'Permalink to "渲染器原理"'},"​")],-1)),i(r,{src:"/diagrams/03-renderer/renderer.svg",alt:"渲染器原理",source:"/notes/03-renderer/renderer.excalidraw"}),e[1]||(e[1]=d(`<h2 id="图文要点" tabindex="-1">图文要点 <a class="header-anchor" href="#图文要点" aria-label="Permalink to &quot;图文要点&quot;">​</a></h2><p>参考 GAMES101 导论：图形学（游戏工业界）≈ 渲染</p><h3 id="_1-什么是渲染" tabindex="-1">① 什么是渲染 <a class="header-anchor" href="#_1-什么是渲染" aria-label="Permalink to &quot;① 什么是渲染&quot;">​</a></h3><p>在游戏工业界，图形学 ≈ 渲染（Rendering）<br>渲染：计算屏幕上每个像素的颜色 (R, G, B)<br>1 个像素 = (34, 177, 76)<br>3 个分量：R 红 · G 绿 · B 蓝，各 8 bit → 24 bit 真彩色</p><h3 id="_2-最基础的渲染器架构" tabindex="-1">② 最基础的渲染器架构 <a class="header-anchor" href="#_2-最基础的渲染器架构" aria-label="Permalink to &quot;② 最基础的渲染器架构&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Color screen_pixels[W][H];                        // 屏幕缓冲：每像素一个颜色</span></span>
<span class="line"><span>for (int y = 0; y &lt; H; y++)                       // 遍历每一行</span></span>
<span class="line"><span>    for (int x = 0; x &lt; W; x++)                   // 遍历每一列</span></span>
<span class="line"><span>        screen_pixels[x][y] = RenderPixel(x, y);  // 核心：算这个像素的颜色</span></span>
<span class="line"><span>present(screen_pixels);                           // 把缓冲显示到屏幕</span></span></code></pre></div><p>RenderPixel(x, y) 是渲染器的核心 —— 后续所有阶段，本质都在回答「一个像素的颜色怎么算」</p><h3 id="_3-渲染器长什么样" tabindex="-1">③ 渲染器长什么样 <a class="header-anchor" href="#_3-渲染器长什么样" aria-label="Permalink to &quot;③ 渲染器长什么样&quot;">​</a></h3><p>场景 几何 · 材质 光照 · 相机 · 渲染器 逐像素计算颜色 · 输出 屏幕像素阵列 (W×H) 两条主流路线：光栅化（逐三角形投影 → 填像素） · 光线追踪（逐像素发射光线求交）</p><h3 id="_4-踩坑记录" tabindex="-1">④ 踩坑记录 <a class="header-anchor" href="#_4-踩坑记录" aria-label="Permalink to &quot;④ 踩坑记录&quot;">​</a></h3><h2 id="先做离线渲染-像素写进-ppm-文件再打开看-比直接上窗口-gpu-简单一个数量级调试时把像素涂成纯色-纯红-纯绿-一眼看出坐标与循环边界是否正确" tabindex="-1">先做离线渲染：像素写进 PPM 文件再打开看，比直接上窗口 / GPU 简单一个数量级<br>调试时把像素涂成纯色（纯红 / 纯绿），一眼看出坐标与循环边界是否正确 <a class="header-anchor" href="#先做离线渲染-像素写进-ppm-文件再打开看-比直接上窗口-gpu-简单一个数量级调试时把像素涂成纯色-纯红-纯绿-一眼看出坐标与循环边界是否正确" aria-label="Permalink to &quot;先做离线渲染：像素写进 PPM 文件再打开看，比直接上窗口 / GPU 简单一个数量级&lt;br&gt;调试时把像素涂成纯色（纯红 / 纯绿），一眼看出坐标与循环边界是否正确&quot;">​</a></h2><blockquote><p>📝 本页由脚本从 <a href="https://github.com/zhangxianjue-com/CG/blob/main/notes/03-renderer/renderer.excalidraw" target="_blank" rel="noreferrer"><code>notes/03-renderer/renderer.excalidraw</code></a> 自动生成。 原图：<a href="/CG/notes/03-renderer/renderer.excalidraw.html">03-renderer/renderer.excalidraw</a>（可用 <a href="https://excalidraw.com" target="_blank" rel="noreferrer">Excalidraw</a> 或 VSCode 扩展打开编辑）</p></blockquote>`,12))])}const g=n(p,[["render",c]]);export{f as __pageData,g as default};
